//////////////////////////////////////////////////////////////////////////////////
// UTUIButtonUploadthing
//////////////////////////////////////////////////////////////////////////////////

"use client";

// Global Imports
import { createId } from "@paralleldrive/cuid2";
import { CircleCheck, GripVertical, Info } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { generatePermittedFileTypes } from "uploadthing/client";

// Local Imports
import { Button } from "@/components/ui/button";
import { useUploadThing } from "@/lib/uploadthing";
import type { UTUIFileStatus, UTUIFunctionsProps, UTUIUploadFile } from "@/lib/uploadthing-ui-types";
import { useUploadthingStore } from "@/store/button-uploadthing-store";

// Body
export default function UTUIButtonUploadthing({ UTUIFunctionsProps }: { UTUIFunctionsProps: UTUIFunctionsProps }) {
  // [1] Refs & States
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { setFiles, historicFiles } = useUploadthingStore();

  // [2] Deriving the accepted file types
  const { routeConfig } = useUploadThing(UTUIFunctionsProps.fileRoute);
  const acceptedFileTypes = generatePermittedFileTypes(routeConfig)
    .fileTypes.map((fileType) => {
      if (fileType.includes("/")) {
        return fileType;
      } else {
        return `${fileType}/*`;
      }
    })
    .join(",");

  // [3] Handlers
  const handleButtonClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = e.target.files;
    if (selectedFiles && selectedFiles.length > 0) {
      // Convert FileList to Array and add to store
      setFiles(
        Array.from(selectedFiles).map((fileObj) => ({
          file: fileObj,
          id: createId(),
          fileObj,
          status: "pending" as UTUIFileStatus, // Use type assertion here
          createdAt: new Date(),
        })),
      );

      // Reset the input to allow selecting the same files again
      if (fileInputRef.current) {
        fileInputRef.current.value = "";
      }
    }
  };

  // [4] JSX
  return (
    <div className="flex flex-col gap-8 text-sm">
      <div>
        <input
          type="file"
          ref={fileInputRef}
          onChange={handleFileChange}
          style={{ display: "none" }}
          multiple
          accept={acceptedFileTypes}
        />
        <Button className="w-fit" onClick={handleButtonClick}>
          Select Files to Upload
        </Button>
      </div>

      {historicFiles.map((fileObj) => (
        <DisplayingToasts key={fileObj.id} uploadFile={fileObj} UTUIFunctionsProps={UTUIFunctionsProps} />
      ))}
    </div>
  );
}

//////////////////////////////////////////////////////////////////////////////////
// Displaying Toasts
//////////////////////////////////////////////////////////////////////////////////

function DisplayingToasts({
  uploadFile,
  UTUIFunctionsProps,
}: {
  uploadFile: UTUIUploadFile;
  UTUIFunctionsProps: UTUIFunctionsProps;
}) {
  // [1] Refs & States
  const isMounted = useRef(true);
  const hasStartedUpload = useRef(false);
  const [progress, setProgress] = useState(0);
  const toastIdRef = useRef<string | number | undefined>(undefined);
  const { updateFileStatus, removeFile } = useUploadthingStore();

  // [2] Uploadthing
  const { startUpload, isUploading } = useUploadThing(UTUIFunctionsProps.fileRoute, {
    uploadProgressGranularity: "fine",
    onUploadProgress: (progress) => {
      if (isMounted.current) {
        setProgress(progress);

        // Your additional code here
        UTUIFunctionsProps.onUploadProgress?.(progress);
      }
    },
    onClientUploadComplete: (res) => {
      if (isMounted.current && res?.[0]) {
        updateFileStatus(uploadFile.id, "complete", res[0].url);

        // Your additional code here
        UTUIFunctionsProps.onClientUploadComplete?.(res);
      }
    },
    onUploadError: (error) => {
      if (isMounted.current) {
        updateFileStatus(uploadFile.id, "error");

        // Your additional code here
        UTUIFunctionsProps.onUploadError?.(error);
      }
    },
    onBeforeUploadBegin: UTUIFunctionsProps.onBeforeUploadBegin,
    onUploadBegin: UTUIFunctionsProps.onUploadBegin,
  });

  // [3] Effects
  // When a file isn't uploading
  useEffect(() => {
    if (!hasStartedUpload.current && !isUploading) {
      hasStartedUpload.current = true;

      startUpload([uploadFile.file]);
      updateFileStatus(uploadFile.id, "uploading");

      // Adding a toast for the upload
      const id = toast.custom(() => <ToastComponent progress={progress} uploadFile={uploadFile} />, {
        duration: Infinity,
      });
      toastIdRef.current = id;

      return;
    }
    // oxlint-disable-next-line react/exhaustive-deps
  }, []);

  // When a file changes its status during the uploading process
  useEffect(() => {
    if (uploadFile.status === "complete" && toastIdRef.current) {
      toast.custom(() => <ToastComponentCompleted uploadFile={uploadFile} />, {
        id: toastIdRef.current,
        duration: 4000,
      });

      // Removing file from state
      removeFile(uploadFile.id);

      return;
    }

    if (uploadFile.status === "error" && toastIdRef.current) {
      toast.custom(() => <ToastComponentError uploadFile={uploadFile} />, {
        id: toastIdRef.current,
        duration: 4000,
      });

      return;
    }
  }, [uploadFile, removeFile]);

  // When a file starts its uploading process
  useEffect(() => {
    if (toastIdRef.current && isUploading) {
      // Update the progress inside the toast
      toast.custom(() => <ToastComponent progress={progress} uploadFile={uploadFile} />, { id: toastIdRef.current });
    }
  }, [progress, isUploading, uploadFile]);

  return <div className="hidden">{uploadFile.id}</div>;
}

function ToastComponent({ progress, uploadFile }: { progress: number; uploadFile: UTUIUploadFile }) {
  return (
    <div className="flex h-16 w-full select-none items-center gap-4 rounded-md border px-4 text-xs shadow-lg sm:w-96">
      <div className="min-w-11">
        <CircularProgressBar percentage={progress} />
      </div>
      <p className="truncate">Uploading {uploadFile.file.name}</p>
      <GripVertical className="ml-auto min-w-10 stroke-1" />
    </div>
  );
}

function ToastComponentCompleted({ uploadFile }: { uploadFile: UTUIUploadFile }) {
  return (
    <div className="flex h-16 w-full select-none items-center gap-4 rounded-md border px-4 text-xs shadow-lg sm:w-96">
      <CircleCheck className="min-w-6 fill-foreground stroke-background stroke-1" />
      <div className="flex flex-col truncate">
        <p className="truncate">File uploaded successfully!</p>
        <p className="truncate">Uploaded {uploadFile.file.name}</p>
      </div>
      <GripVertical className="ml-auto min-w-10 stroke-1" />
    </div>
  );
}

function ToastComponentError({ uploadFile }: { uploadFile: UTUIUploadFile }) {
  return (
    <div className="flex h-16 w-full select-none items-center gap-4 truncate rounded-md border px-4 text-xs shadow-lg sm:w-96">
      <Info className="min-w-6 fill-foreground stroke-background stroke-1" />
      <div className="flex flex-col truncate">
        <p className="truncate">File couldn&apos;t be uploaded</p>
        <p className="truncate">{uploadFile.file.name}</p>
      </div>
      <GripVertical className="ml-auto min-w-10 stroke-1" />
    </div>
  );
}

//////////////////////////////////////////////////////////////////////////////////
// Circular Progress Bar
//////////////////////////////////////////////////////////////////////////////////

function CircularProgressBar({ percentage }: { percentage: number }) {
  // [1] JSX
  return (
    <div className="relative">
      <svg className="-rotate-90" viewBox="0 0 36 36" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
        <circle cx="18" cy="18" r="16" fill="none" className="stroke-current stroke-2 text-primary"></circle>
        <circle
          cx="18"
          cy="18"
          r="16"
          fill="none"
          className="stroke-current stroke-2 text-secondary"
          strokeDasharray="100"
          strokeDashoffset={percentage}
          strokeLinecap="round"
        ></circle>
      </svg>
      <div className="absolute start-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 transform">
        <span className="text-center text-xs text-primary">{percentage}</span>
      </div>
    </div>
  );
}

// Global Imports

import { create } from "zustand";

// Local Imports

// Body
export type FileStatus = "pending" | "uploading" | "complete" | "error";

export interface UploadFile {
  id: string;
  file: File;
  status: FileStatus;
  url?: string;
  createdAt: Date;
}

interface FilesState {
  files: UploadFile[];
  historicFiles: UploadFile[];
  setFiles: (newFiles: UploadFile[]) => void;
  updateFileStatus: (id: string, status: FileStatus, url?: string) => void;
  removeFile: (id: string) => void;
}

export const useUploadthingStore = create<FilesState>()((set) => ({
  files: [],
  historicFiles: [],
  setFiles: (newFiles) =>
    set((state) => {
      // Check if the file is already in the historicFiles array. If not, add it as well
      const newHistoricFiles = Array.from(newFiles).filter(
        (file) => !state.historicFiles.some((historicFile) => historicFile.id === file.id),
      );

      return {
        files: newFiles,
        historicFiles: [...state.historicFiles, ...newHistoricFiles],
      };
    }),
  updateFileStatus: (id, status, url) =>
    set((state) => ({
      files: state.files.map((item) => (item.id === id ? { ...item, status, url } : item)),
      historicFiles: state.historicFiles.map((item) => (item.id === id ? { ...item, status, url } : item)),
    })),
  removeFile: (id) =>
    set((state) => ({
      historicFiles: state.historicFiles.filter((item) => item.id !== id),
    })),
}));

"use client";

import { useTheme } from "next-themes";
import { Toaster as Sonner } from "sonner";

type ToasterProps = React.ComponentProps<typeof Sonner>;

const Toaster = ({ ...props }: ToasterProps) => {
  const { theme = "system" } = useTheme();

  return (
    <Sonner
      theme={theme as ToasterProps["theme"]}
      className="toaster group"
      toastOptions={{
        classNames: {
          toast:
            "group toast group-[.toaster]:bg-background rounded-md group-[.toaster]:text-foreground group-[.toaster]:border-border group-[.toaster]:shadow-lg",
          description: "group-[.toast]:text-muted-foreground",
          actionButton:
            "group-[.toast]:bg-primary group-[.toast]:text-primary-foreground",
          cancelButton:
            "group-[.toast]:bg-muted group-[.toast]:text-muted-foreground",
        },
      }}
      {...props}
    />
  );
};

export { Toaster };

import type { OurFileRouter } from "@/app/api/uploadthing/core";
import type { Json, MaybePromise, UploadThingError } from "@uploadthing/shared";
import type { ClientUploadedFileData, EndpointArg } from "uploadthing/types";

export type UTUIFileStatus = "pending" | "uploading" | "complete" | "error";

export interface UTUIUploadFile {
  id: string;
  file: File;
  status: UTUIFileStatus;
  url?: string;
  createdAt: Date;
}

export interface UTUIFunctionsProps {
  fileRoute: EndpointArg<OurFileRouter, keyof OurFileRouter>;
  onUploadProgress?: (progress: number) => void;
  onClientUploadComplete?:
    | ((
        res: ClientUploadedFileData<{
          uploadedBy: string;
        }>[],
      ) => MaybePromise<void>)
    | undefined;
  onUploadError?: (error: UploadThingError<Json>) => void;
  onBeforeUploadBegin?: ((files: File[]) => Promise<File[]> | File[]) | undefined;
  onUploadBegin?: ((fileName: string) => void) | undefined;
}

// Converts the size into readable format
export function formatBytes(bytes: number, decimals = 1) {
  if (!Number.isFinite(bytes) || bytes <= 0) return "0 B";

  const k = 1024;
  const dm = decimals < 0 ? 0 : decimals;
  const sizes = ["B", "KB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB"];

  const i = Math.min(Math.floor(Math.log(bytes) / Math.log(k)), sizes.length - 1);

  return `${parseFloat((bytes / k ** i).toFixed(dm))} ${sizes[i]}`;
}

// Return the amount of file uploaded
export function getUploadedAmount(progress: number, fileSize: number) {
  const uploadedAmount = (progress / 100) * fileSize;
  return formatBytes(uploadedAmount);
}

// Capitalize the first letter
export function capitalizeFirstLetter(string: string) {
  return string.charAt(0).toUpperCase() + string.slice(1);
}

import type { OurFileRouter } from "@/app/api/uploadthing/core";
